{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.sirona_child_level_Planning as WITH sku_revenue AS ( SELECT UPPER(SKU) SKU, PRODUCTNAME, SUM(suborder_quantity) AS Quantity, ROUND(SUM(selling_price),2) AS selling_price, ROUND(SUM(suborder_quantity * selling_price),2) AS total_revenue FROM maplemonk.sirona_wh_EasyEcom_FACT_ITEMS WHERE DATE(order_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 90 DAY) GROUP BY 1,2 ), daily AS ( SELECT UPPER(SKU) SKU, ORDER_DATE, SUM(suborder_quantity) AS daily_qty FROM maplemonk.sirona_wh_EasyEcom_FACT_ITEMS WHERE DATE(order_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 90 DAY) GROUP BY 1,2 ), std_calc AS ( SELECT UPPER(SKU) SKU, ROUND(STDDEV_POP(daily_qty),2) AS std_dev FROM daily GROUP BY 1 ), inv AS ( SELECT UPPER(Sku) SKU, SUM(CAST(Quantity AS INT64)) AS Current_Inventory FROM `Maplemonk.Sirona_inv_db_consolidated_inventory` WHERE DATE(_airbyte_emitted_at) = CURRENT_DATE() AND Company_Name = \'SIRONA HYGIENE PRIVATE LIMITED(Tauru)\' GROUP BY 1 ), cl AS ( SELECT UPPER(sku) SKU, CAST(DDA AS FLOAT64) AS DDA, CAST(Zscore AS FLOAT64) AS Zscore, CAST(LT AS INT64) AS LT, CAST(ROF AS INT64) AS ROF FROM `Maplemonk.Sirona_Google_sheet_db_Child_Level` ), calc AS ( SELECT s.*, ROUND(SAFE_DIVIDE(total_revenue, SUM(total_revenue) OVER ()) * 100,2) AS revenue_pct, ROUND( SUM(total_revenue) OVER (ORDER BY total_revenue DESC) / SUM(total_revenue) OVER () * 100,2) AS cumulative_pct FROM sku_revenue s ), final_metrics AS ( SELECT c.*, inv.Current_Inventory, cl.DDA, cl.Zscore, cl.LT, cl.ROF, sc.std_dev, CASE WHEN cumulative_pct <= 80 THEN \'A\' WHEN cumulative_pct <= 95 THEN \'B\' ELSE \'C\' END AS ABC, ROUND(SAFE_DIVIDE(Quantity,90),2) AS Avg_Daily_Demand, ROUND( SAFE_DIVIDE(sc.std_dev, SAFE_DIVIDE(Quantity,90)) ,2) AS CV FROM calc c LEFT JOIN std_calc sc USING (SKU) LEFT JOIN inv ON TRIM(UPPER(c.SKU)) = TRIM(UPPER(inv.SKU)) LEFT JOIN cl ON TRIM(UPPER(c.SKU)) = TRIM(UPPER(cl.SKU)) ), final_classification AS ( SELECT *, CASE WHEN CV <= 0.5 THEN \'X\' WHEN CV <= 1 THEN \'Y\' ELSE \'Z\' END AS XYZ, CONCAT(ABC, CASE WHEN CV <= 0.5 THEN \'X\' WHEN CV <= 1 THEN \'Y\' ELSE \'Z\' END ) AS Combined_Class FROM final_metrics ) SELECT coalesce(A.SKU,b.sku) SKU ,PRODUCTNAME ,QUANTITY ,SELLING_PRICE ,TOTAL_REVENUE ,revenue_pct ,cumulative_pct ,Current_Inventory ,DDA ,ZSCORE ,LT,ROF,STD_DEV,ABC,CV,XYZ ,AVG_DAILY_DEMAND ,COMBINED_CLASS ,CASE WHEN Combined_Class = \'AX\' THEN 99 WHEN Combined_Class = \'AY\' THEN 97 WHEN Combined_Class = \'AZ\' THEN 92 WHEN Combined_Class = \'BX\' THEN 95 WHEN Combined_Class = \'BY\' THEN 93 WHEN Combined_Class = \'BZ\' THEN 88 WHEN Combined_Class = \'CX\' THEN 98 WHEN Combined_Class = \'CY\' THEN 90 WHEN Combined_Class = \'CZ\' THEN 80 END AS Target_Serviceability ,b.Product_Status FROM final_classification a left join ( SELECT UPPER(Sku) SKU,Product_Status FROM `Maplemonk.Sirona_GS_DB_Master_sheet`) b ON TRIM(UPPER(a.SKU)) = TRIM(UPPER(b.SKU)); CREATE OR REPLACE TABLE Maplemonk.sirona_db_emiza_planning_fact_items AS SELECT EE.sku AS SKU, EE.PRODUCTNAME AS PRODUCT_NAME, EE.ORDER_DATE, EE.selling_price AS SELLING_PRICE, EE.suborder_quantity AS SALES_QTY, EE.Warehouse_name AS WAREHOUSE_NAME, INV.Available_Stock FROM MAPLEMONK.sirona_wh_EasyEcom_FACT_ITEMS EE LEFT JOIN ( SELECT TRIM(UPPER(sku)) AS SKU, TRIM(UPPER(company_name)) AS COMPANY_NAME, SUM(CAST(Quantity AS INT64)) AS Available_Stock FROM `Maplemonk.Sirona_inv_db_consolidated_inventory` WHERE DATE(_airbyte_emitted_at) = CURRENT_DATE() GROUP BY 1,2 ) INV ON TRIM(UPPER(EE.SKU)) = INV.SKU AND TRIM(UPPER(EE.WAREHOUSE_NAME)) = INV.COMPANY_NAME WHERE UPPER(EE.WAREHOUSE_NAME) IN ( \'SIRONA HYGIENE PRIVATE LIMITED(EMZ - KARNATAKA)\', \'SIRONA HYGIENE PRIVATE LIMITED(TAURU)\', \'SIRONA HYGIENE PVT LTD(EMZ-HYD)\', \'SIRONA HYGIENE PVT LTD(EMZ-MUMBAI)\', \'SIRONA HYGIENE PRIVATE LIMITED(EMZ - WEST BENGAL)\' ) AND DATE(EE.order_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 90 DAY) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            